def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    for ri, row in enumerate(grid):
        n = len(row)
        if n < 2 or row[-1] != bg:
            continue
        # Locate the terminal run of the background color.
        start = n - 1
        while start > 0 and row[start - 1] == bg:
            start -= 1
        if start == 0:
            continue

        # A two-run row encodes a foreground prefix followed by its blank tail.
        first = row[0]
        k = 0
        while k < n and row[k] == first:
            k += 1
        if k == start and first != bg:
            out[ri][start:] = [1] * (n - start)
            continue

        # If another row has the same prefix and a completed continuation,
        # use it as the pattern source; additions are marked with color 1.
        best = None
        best_score = -1
        for rj, other in enumerate(grid):
            if rj == ri or len(other) != n or other[:start] != row[:start]:
                continue
            score = sum(v != bg for v in other[start:])
            if score > best_score:
                best, best_score = other, score
        if best is not None and best_score > 0:
            for c in range(start, n):
                if row[c] == bg and best[c] != bg:
                    out[ri][c] = 1
            continue

        # Otherwise continue a clear short repeating motif from the row itself.
        # Select the shortest period supported by the last several known cells.
        chosen = None
        for period in range(1, min(6, start) + 1):
            support = min(start, max(6, period * 3))
            seq = row[start - support:start]
            if support >= period * 2 and all(
                seq[i] == seq[i - period] for i in range(period, support)
            ):
                chosen = period
                break
        if chosen is not None:
            for c in range(start, n):
                if row[c] == bg and row[c - chosen] != bg:
                    out[ri][c] = 1

    return out

