def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # A simple encoded row: a solid non-background prefix followed by
    # a solid background suffix. Mark that suffix.
    for r, row in enumerate(grid):
        if row[0] == bg or row[-1] != bg:
            continue
        k = 0
        while k < w and row[k] == row[0]:
            k += 1
        if 0 < k < w and all(v == bg for v in row[k:]):
            out[r][k:] = [1] * (w - k)

    # Find contiguous multi-row motifs (all-background rows separate objects).
    blocks = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        if r - start >= 2:
            blocks.append((start, r))

    # Repeated motif blocks may have omissions in either copy. Transfer the
    # union of their foreground masks, using 1 to mark newly supplied cells.
    for i in range(len(blocks)):
        a0, a1 = blocks[i]
        for j in range(i + 1, len(blocks)):
            b0, b1 = blocks[j]
            if a1 - a0 != b1 - b0:
                continue
            n = (a1 - a0) * w
            equal = 0
            for dr in range(a1 - a0):
                for c in range(w):
                    if grid[a0 + dr][c] == grid[b0 + dr][c]:
                        equal += 1
            if equal / n < 0.38:
                continue
            # Require corresponding rows to share meaningful foreground structure.
            overlap = union = 0
            for dr in range(a1 - a0):
                for c in range(w):
                    fa = grid[a0 + dr][c] != bg
                    fb = grid[b0 + dr][c] != bg
                    overlap += fa and fb
                    union += fa or fb
            if union == 0 or overlap / union < 0.25:
                continue
            for dr in range(a1 - a0):
                for c in range(w):
                    ra, rb = a0 + dr, b0 + dr
                    if grid[ra][c] == bg and grid[rb][c] != bg:
                        out[ra][c] = 1
                    if grid[rb][c] == bg and grid[ra][c] != bg:
                        out[rb][c] = 1

    return out

