def transform(grid):
    """Highlight foreground cells in the periodic continuation of row tails."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])

    # Each row's trailing run is the erased part of its horizontal motif.
    for r, row in enumerate(grid):
        if w < 3 or row[-1] != bg:
            continue
        start = w - 1
        while start > 0 and row[start - 1] == bg:
            start -= 1
        if start == 0:
            continue
        prefix = row[:start]
        # Choose the shortest period supported by at least two repetitions
        # immediately before the blank tail.
        period = None
        support = 0
        for p in range(1, min(8, len(prefix) // 2) + 1):
            n = min(len(prefix), max(2 * p, 4))
            s = len(prefix) - n
            if all(prefix[i] == prefix[i - p] for i in range(s + p, len(prefix))):
                period, support = p, n
                break
        if period is not None:
            for c in range(start, w):
                expected = row[c - period]
                if expected != bg:
                    out[r][c] = 1

    # A repeated row motif may continue past the right edge of its earlier
    # copy. Mark matching foreground extensions in later rows when the recent
    # suffix itself provides a clear short period.
    for r, row in enumerate(grid):
        if w < 4:
            continue
