        best = None
        for p in range(1, min(8, w // 3) + 1):
            # Search suffixes of at least three periods, preferring the longest.
            n = min(w, max(3 * p, 6))
            s = w - n
            if n >= 2 * p and all(row[i] == row[i - p] for i in range(s + p, w)):
                best = (p, s)
                break
        if best is None:
            continue
        p, s = best
        # Only mark the continuation after a previously matching row's
        # known region; this avoids recoloring the reference motif itself.
        for q in range(r):
            other = grid[q]
            if len(other) != w:
                continue
            same = 0
            for c in range(s):
                same += row[c] == other[c]
            if same < max(4, int(0.65 * s)):
                continue
