def _periodic_suffix(row, bg):
    """Return (period, start) for the shortest repeated suffix pattern."""
    n = len(row)
    for p in range(1, min(8, n // 2) + 1):
        # Require at least two full repetitions ending at the row boundary.
        start = n - 2 * p
        if all(row[i] == row[i - p] for i in range(start + p, n)):
            # Extend the verified periodic region leftward.
            while start > 0 and row[start - 1] == row[start - 1 + p]:
                start -= 1
            return p, start
    return None


