        best_score = 0
        for q, donor in enumerate(grid):
            if q == r:
                continue
            periodic = _periodic_suffix(donor, bg)
            if periodic is None:
                continue
            p, periodic_start = periodic
            for shift in range(-w + 1, w):
                # donor column = target column + shift
                c = tail - 1
                while c >= 0 and 0 <= c + shift < w and row[c] == donor[c + shift]:
