            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            for cell in component:
                sizes[cell] = len(component)

    # Extend the background tail of a row when its rightmost foreground pixel
    # is part of a multi-cell component.
    for r, row in enumerate(grid):
        c = w - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c >= 0 and c < w - 1 and sizes.get((r, c), 0) >= 2:
            for x in range(c + 1, w):
                out[r][x] = 1
    return out

