def transform(grid):
    h, w = len(grid), len(grid[0])
    # The task divider is a uniform centered row or column, separating equal panels.
    panels = None
    for c in range(w):
        if 2 * c + 1 == w and len({row[c] for row in grid}) == 1:
            panels = ([[row[:c] for row in grid]], [[row[c + 1:] for row in grid]])
            break
    if panels is None:
        for r in range(h):
            if 2 * r + 1 == h and len(set(grid[r])) == 1:
                panels = (grid[:r], grid[r + 1:])
                break
    if panels is None:
        raise ValueError("No centered uniform divider")
    a, b = panels
    # The marker panel is the more uniform panel: it has a solid background and
    # sparse marker-color cells. The output background is that sparse color.
    def concentration(panel):
        counts = Counter(x for row in panel for x in row)
        return counts.most_common(1)[0][1] / sum(counts.values())
    pattern, markers = (a, b) if concentration(a) <= concentration(b) else (b, a)
    counts = Counter(x for row in markers for x in row)
    marker_color = min(counts, key=counts.get)
    return [[3 if pattern[i][j] == marker_color and markers[i][j] == marker_color
             else marker_color for j in range(len(pattern[0]))]
            for i in range(len(pattern))]

