            groups.setdefault(key, set()).add(pos)
        best = (0, None, None, None)
        for key, positions in groups.items():
            for p in positions:
                if p - 1 not in positions:
                    n = 0
                    while p + n in positions:
                        n += 1
                    if n > best[0]:
                        best = (n, key, p, p+n-1)
        return best

